import pulp

# Problem data
shipments = {
    1: [(5, 8), (4, 7), (1, 4), (2, 8), (3, 8)],   # S1
    2: [(5, 5), (3, 3), (2, 8), (1, 1), (4, 10)],  # S2
    3: [(2, 1), (1, 9), (5, 2), (3, 2), (4, 7)],   # S3
    4: [(1, 5), (3, 5), (5, 4), (4, 3), (2, 10)],  # S4
    5: [(3, 6), (2, 7), (1, 3), (4, 6), (5, 7)],   # S5
}

# Extract hub and processing time for each operation
h = {}  # h[s,k] = hub for k-th operation of shipment s
p = {}  # p[s,k] = processing time for k-th operation of shipment s
for s in range(1, 6):
    for k in range(1, 6):
        h[s, k] = shipments[s][k-1][0]
        p[s, k] = shipments[s][k-1][1]

# Big-M: upper bound on makespan (sum of all processing times)
M = sum(p[s, k] for s in range(1, 6) for k in range(1, 6))

# Create model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Decision variables
# x[s,k]: start time of k-th operation of shipment s
x = pulp.LpVariable.dicts("x", ((s, k) for s in range(1, 6) for k in range(1, 6)), 
                          lowBound=0, cat='Continuous')

# C: makespan
C = pulp.LpVariable("C", lowBound=0, cat='Continuous')

# y[s1,k1,s2,k2]: binary, 1 if (s1,k1) precedes (s2,k2) on same hub
# Only define for pairs that use the same hub, with s1 < s2 to avoid duplicates
y = {}
for s1 in range(1, 6):
    for k1 in range(1, 6):
        for s2 in range(s1+1, 6):
            for k2 in range(1, 6):
                if h[s1, k1] == h[s2, k2]:
                    y[s1, k1, s2, k2] = pulp.LpVariable(f"y_{s1}_{k1}_{s2}_{k2}", cat='Binary')

# Objective: minimize makespan
model += C

# Constraint 1: Sequence constraints - operations within same shipment
for s in range(1, 6):
    for k in range(1, 5):
        model += x[s, k] + p[s, k] <= x[s, k+1]

# Constraint 2: Makespan definition
for s in range(1, 6):
    model += x[s, 5] + p[s, 5] <= C

# Constraint 3: Hub capacity - no overlap on same hub
for s1 in range(1, 6):
    for k1 in range(1, 6):
        for s2 in range(s1+1, 6):
            for k2 in range(1, 6):
                if h[s1, k1] == h[s2, k2]:
                    # Either (s1,k1) before (s2,k2) or vice versa
                    model += x[s1, k1] + p[s1, k1] <= x[s2, k2] + M * (1 - y[s1, k1, s2, k2])
                    model += x[s2, k2] + p[s2, k2] <= x[s1, k1] + M * y[s1, k1, s2, k2]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal Makespan: {pulp.value(C)}")
print("\nSchedule:")
for s in range(1, 6):
    print(f"\nShipment S{s}:")
    for k in range(1, 6):
        start = pulp.value(x[s, k])
        end = start + p[s, k]
        print(f"  Op {k}: Hub H{h[s, k]}, Start={start:.2f}, End={end:.2f}, Duration={p[s, k]}")

import pulp

# Define the problem
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Device data: sequence of (station, duration) for each device
devices = {
    1: [(4, 9), (1, 8), (2, 6), (3, 8)],   # D1
    2: [(4, 1), (3, 6), (1, 6), (2, 6)],   # D2
    3: [(1, 10), (3, 3), (4, 7), (2, 10)],  # D3
    4: [(3, 2), (4, 9), (2, 1), (1, 2)]    # D4
}

num_devices = 4
num_operations = 4

# Extract station and processing time for each operation
# m[j][o] = station for operation o of device j (1-indexed)
# p[j][o] = processing time for operation o of device j
m = {}
p = {}
for j in range(1, num_devices + 1):
    m[j] = {}
    p[j] = {}
    for o in range(1, num_operations + 1):
        m[j][o] = devices[j][o-1][0]
        p[j][o] = devices[j][o-1][1]

# Big-M: sum of all processing times
M = sum(sum(p[j][o] for o in range(1, num_operations + 1)) for j in range(1, num_devices + 1))

# Decision Variables
# C[j][o]: completion time of operation o of device j
C = {}
for j in range(1, num_devices + 1):
    C[j] = {}
    for o in range(1, num_operations + 1):
        C[j][o] = pulp.LpVariable(f"C_{j}_{o}", lowBound=0, cat='Continuous')

# C_max: makespan
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# y[(j,o),(j',o')]: binary, 1 if operation (j,o) precedes (j',o') on same station
y = {}
# Find all pairs of operations that use the same station
for j in range(1, num_devices + 1):
    for o in range(1, num_operations + 1):
        for j2 in range(j, num_devices + 1):
            for o2 in range(1, num_operations + 1):
                if j == j2 and o == o2:
                    continue
                if m[j][o] == m[j2][o2]:
                    # Only create variable for j < j2, or j == j2 and o < o2 to avoid duplicates
                    if j < j2 or (j == j2 and o < o2):
                        y[(j, o, j2, o2)] = pulp.LpVariable(f"y_{j}_{o}_{j2}_{o2}", cat='Binary')

# Objective: minimize makespan
model += C_max

# Constraints

# 1. Makespan definition: C_max >= completion time of last operation of each device
for j in range(1, num_devices + 1):
    model += C[j][num_operations] <= C_max

# 2. Precedence constraints within each device
for j in range(1, num_devices + 1):
    for o in range(2, num_operations + 1):
        model += C[j][o] >= C[j][o-1] + p[j][o]

# 3. First operation of each device must finish at least after its processing time
for j in range(1, num_devices + 1):
    model += C[j][1] >= p[j][1]

# 4. Non-overlapping constraints for operations on the same station
for (j, o, j2, o2), var in y.items():
    station = m[j][o]  # same as m[j2][o2]
    # Either (j,o) before (j2,o2): C[j2][o2] >= C[j][o] + p[j2][o2]
    # Or (j2,o2) before (j,o): C[j][o] >= C[j2][o2] + p[j][o]
    model += C[j2][o2] >= C[j][o] + p[j2][o2] - M * (1 - var)
    model += C[j][o] >= C[j2][o2] + p[j][o] - M * var

# Solve with HiGHS
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal makespan: {pulp.value(C_max):.2f}")
print("\nSchedule:")
for j in range(1, num_devices + 1):
    print(f"Device D{j}:")
    for o in range(1, num_operations + 1):
        start = pulp.value(C[j][o]) - p[j][o]
        print(f"  Operation {o}: Station {m[j][o]}, Start={start:.2f}, End={pulp.value(C[j][o]):.2f}, Duration={p[j][o]}")

import pulp

# Define the problem
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Shipment data: (hub, processing_time) for each operation in order
shipments = {
    1: [(2, 2), (1, 2), (3, 6)],   # S1: H2->H1->H3, times [2,2,6]
    2: [(2, 7), (1, 6), (3, 10)],  # S2: H2->H1->H3, times [7,6,10]
    3: [(3, 8), (1, 9), (2, 5)],   # S3: H3->H1->H2, times [8,9,5]
}

num_shipments = 3
num_operations = 3

# Extract processing times and hub assignments
# p[i][k] = processing time for operation k of shipment i (0-indexed)
# h[i][k] = hub for operation k of shipment i
p = {}
h = {}
for i in range(1, num_shipments + 1):
    p[i] = {}
    h[i] = {}
    for k in range(num_operations):
        h[i][k], p[i][k] = shipments[i][k]

# Big-M value (upper bound on makespan)
M = sum(sum(p[i][k] for k in range(num_operations)) for i in range(1, num_shipments + 1))

# Decision Variables

# Start times for each operation of each shipment: continuous
s = {}
for i in range(1, num_shipments + 1):
    for k in range(num_operations):
        s[i, k] = pulp.LpVariable(f"s_{i}_{k}", lowBound=0, cat='Continuous')

# Binary variables for disjunctive constraints (which shipment goes first at each hub)
# y[i,j,h] = 1 if shipment i precedes shipment j at hub h
y = {}
for i in range(1, num_shipments + 1):
    for j in range(i + 1, num_shipments + 1):
        for hub in range(1, 4):
            y[i, j, hub] = pulp.LpVariable(f"y_{i}_{j}_{hub}", cat='Binary')

# Makespan: continuous
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += C_max

# Constraints

# 1. Precedence constraints: operations within a shipment must be in sequence
for i in range(1, num_shipments + 1):
    for k in range(num_operations - 1):
        model += s[i, k + 1] >= s[i, k] + p[i][k], f"precedence_{i}_{k}"

# 2. No overlap at hubs: disjunctive constraints
# For each pair of shipments, check if they share a hub
for i in range(1, num_shipments + 1):
    for j in range(i + 1, num_shipments + 1):
        for k_i in range(num_operations):
            for k_j in range(num_operations):
                hub_i = h[i][k_i]
                hub_j = h[j][k_j]
                if hub_i == hub_j:  # Both shipments use same hub
                    hub = hub_i
                    # If i before j: s[j,k_j] >= s[i,k_i] + p[i][k_i]
                    model += s[j, k_j] >= s[i, k_i] + p[i][k_i] - M * (1 - y[i, j, hub]), f"no_overlap_{i}_{j}_{k_i}_{k_j}_1"
                    # If j before i: s[i,k_i] >= s[j,k_j] + p[j][k_j]
                    model += s[i, k_i] >= s[j, k_j] + p[j][k_j] - M * y[i, j, hub], f"no_overlap_{i}_{j}_{k_i}_{k_j}_2"

# 3. Makespan constraints: C_max >= completion time of each shipment
for i in range(1, num_shipments + 1):
    model += C_max >= s[i, num_operations - 1] + p[i][num_operations - 1], f"makespan_{i}"

# Solve with HiGHS
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal Makespan: {pulp.value(C_max)}")
print("\nDetailed Schedule:")
for i in range(1, num_shipments + 1):
    print(f"\nShipment S{i}:")
    for k in range(num_operations):
        start = pulp.value(s[i, k])
        end = start + p[i][k]
        print(f"  Hub H{h[i][k]}: start={start}, end={end}, duration={p[i][k]}")

import pulp

# Problem data
routes = {
    'R1': [('C3', 10), ('C2', 1), ('C1', 1), ('C4', 5)],
    'R2': [('C2', 7), ('C1', 9), ('C4', 3), ('C3', 5)],
    'R3': [('C1', 5), ('C2', 3), ('C4', 9), ('C3', 2)],
    'R4': [('C3', 7), ('C2', 2), ('C4', 2), ('C1', 9)]
}

jobs = ['R1', 'R2', 'R3', 'R4']
machines = ['C1', 'C2', 'C3', 'C4']

# Build operation index: for each job, list of (machine, duration, sequence_position)
job_operations = {}
for j, ops in routes.items():
    job_operations[j] = []
    for pos, (m, d) in enumerate(ops):
        job_operations[j].append((m, d, pos))

# Map: which jobs need which machine
jobs_on_machine = {m: [] for m in machines}
for j, ops in job_operations.items():
    for m, d, pos in ops:
        jobs_on_machine[m].append((j, d, pos))

# Big-M value (upper bound on makespan)
M = sum(d for ops in routes.values() for (_, d) in ops)  # Total processing time = 100

# Create model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Decision Variables
# Start time of each operation
s = {}  # s[j][m] = start time of job j on machine m
for j in jobs:
    s[j] = {}
    for m, d, pos in job_operations[j]:
        s[j][m] = pulp.LpVariable(f"s_{j}_{m}", lowBound=0, cat='Continuous')

# Binary sequencing variables: y[i][j][m] = 1 if job i precedes job j on machine m
y = {}
for m in machines:
    y[m] = {}
    jobs_m = [j for (j, d, pos) in jobs_on_machine[m]]
    for i in jobs_m:
        y[m][i] = {}
        for j in jobs_m:
            if i < j:  # Only create for i < j to avoid duplicates
                y[m][i][j] = pulp.LpVariable(f"y_{i}_{j}_{m}", cat='Binary')

# Makespan
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += C_max

# Constraint 1: Precedence constraints - operations in each job must follow sequence
for j in jobs:
    ops = job_operations[j]
    for k in range(len(ops) - 1):
        m1, d1, pos1 = ops[k]
        m2, d2, pos2 = ops[k + 1]
        # Start of next >= completion of previous
        model += s[j][m2] >= s[j][m1] + d1, f"precedence_{j}_{m1}_{m2}"

# Constraint 2: Machine capacity - no overlap on same machine
for m in machines:
    jobs_m = jobs_on_machine[m]
    for idx1, (j1, d1, pos1) in enumerate(jobs_m):
        for idx2, (j2, d2, pos2) in enumerate(jobs_m):
            if j1 < j2:  # Only for distinct jobs, using ordering to avoid duplicates
                # Either j1 before j2, or j2 before j1
                # If y[j1][j2][m] = 1: s[j2][m] >= s[j1][m] + d1
                # If y[j1][j2][m] = 0: s[j1][m] >= s[j2][m] + d2
                model += s[j2][m] >= s[j1][m] + d1 - M * (1 - y[m][j1][j2]), f"disj1_{m}_{j1}_{j2}"
                model += s[j1][m] >= s[j2][m] + d2 - M * y[m][j1][j2], f"disj2_{m}_{j1}_{j2}"

# Constraint 3: Makespan definition - must cover all completions
for j in jobs:
    for m, d, pos in job_operations[j]:
        model += C_max >= s[j][m] + d, f"makespan_{j}_{m}"

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal Makespan: {pulp.value(C_max)}")
print("\nSchedule:")
for j in jobs:
    print(f"\n{j}:")
    for m, d, pos in job_operations[j]:
        start = pulp.value(s[j][m])
        print(f"  {m}: start={start:.2f}, duration={d}, end={start+d:.2f}")

import pulp

# Problem data
patients = ['A', 'B', 'C']
operations = [1, 2, 3]
devices = ['X', 'Y', 'Z']

# (device, duration) for each patient and operation
# Patient A: (X,2), (Z,4), (Y,6)
# Patient B: (X,1), (Y,2), (Z,3)
# Patient C: (Z,10), (X,9), (Y,10)
task_data = {
    'A': {1: ('X', 2), 2: ('Z', 4), 3: ('Y', 6)},
    'B': {1: ('X', 1), 2: ('Y', 2), 3: ('Z', 3)},
    'C': {1: ('Z', 10), 2: ('X', 9), 3: ('Y', 10)}
}

# Extract duration and device for each (patient, operation)
duration = {}
device = {}
for i in patients:
    for k in operations:
        dev, dur = task_data[i][k]
        device[(i, k)] = dev
        duration[(i, k)] = dur

# Big-M: sum of all durations = 2+4+6+1+2+3+10+9+10 = 57
M = 60

# Create model
model = pulp.LpProblem("hospital_scheduling", pulp.LpMinimize)

# Decision variables
# Start time of each operation (continuous, non-negative)
s = pulp.LpVariable.dicts("start", ((i, k) for i in patients for k in operations), 
                          lowBound=0, cat='Continuous')

# Makespan
C_max = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Binary variables for disjunctions (which operation comes first on same device)
# Only need i < j to avoid duplicates
y = {}
for i in patients:
    for j in patients:
        if i < j:  # lexicographic comparison works for strings
            for k in operations:
                for l in operations:
                    if device[(i, k)] == device[(j, l)]:
                        y[(i, k, j, l)] = pulp.LpVariable(f"y_{i}_{k}_{j}_{l}", cat='Binary')

# Objective: minimize makespan
model += C_max

# Constraint 1: Makespan >= completion time of last operation for each patient
for i in patients:
    model += s[(i, 3)] + duration[(i, 3)] <= C_max

# Constraint 2: Precedence within each patient
for i in patients:
    for k in [1, 2]:
        model += s[(i, k)] + duration[(i, k)] <= s[(i, k+1)]

# Constraint 3: Disjunctive constraints - no overlap on same device
for i in patients:
    for j in patients:
        if i < j:
            for k in operations:
                for l in operations:
                    if device[(i, k)] == device[(j, l)]:
                        # Either (i,k) before (j,l) or vice versa
                        model += s[(i, k)] + duration[(i, k)] <= s[(j, l)] + M * (1 - y[(i, k, j, l)])
                        model += s[(j, l)] + duration[(j, l)] <= s[(i, k)] + M * y[(i, k, j, l)]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Makespan (C_max): {pulp.value(C_max)}")

print("\nSchedule:")
for i in patients:
    for k in operations:
        start = pulp.value(s[(i, k)])
        end = start + duration[(i, k)]
        dev = device[(i, k)]
        print(f"Patient {i}, Op {k} ({dev}, dur={duration[(i,k)]}): start={start:.2f}, end={end:.2f}")

import pulp

# Create the model
model = pulp.LpProblem("Power_Grid_Optimization", pulp.LpMinimize)

# Define plants and centers
plants = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta', 'Eta']
centers = ['Delta', 'Epsilon', 'Zeta', 'Eta', 'Theta', 'Iota', 'Kappa']

# Plant generation capacities
plant_capacity = {
    'Alpha': 84,
    'Beta': 86,
    'Gamma': 91,
    'Delta': 100,
    'Epsilon': 76,
    'Zeta': 23,
    'Eta': 99
}

# Center demands
center_demand = {
    'Delta': 84,
    'Epsilon': 99,
    'Zeta': 36,
    'Eta': 86,
    'Theta': 92,
    'Iota': 87,
    'Kappa': 75
}

# Transmission costs and capacities: cost[i][j], capacity[i][j]
# From Plant Alpha
cost_Alpha = {'Delta': 2, 'Epsilon': 5, 'Zeta': 10, 'Eta': 3, 'Theta': 7, 'Iota': 2, 'Kappa': 1}
cap_Alpha = {'Delta': 63, 'Epsilon': 10, 'Zeta': 66, 'Eta': 84, 'Theta': 18, 'Iota': 39, 'Kappa': 69}

# From Plant Beta
cost_Beta = {'Delta': 1, 'Epsilon': 2, 'Zeta': 6, 'Eta': 8, 'Theta': 6, 'Iota': 2, 'Kappa': 8}
cap_Beta = {'Delta': 67, 'Epsilon': 75, 'Zeta': 87, 'Eta': 55, 'Theta': 65, 'Iota': 38, 'Kappa': 28}

# From Plant Gamma
cost_Gamma = {'Delta': 6, 'Epsilon': 10, 'Zeta': 5, 'Eta': 8, 'Theta': 4, 'Iota': 3, 'Kappa': 9}
cap_Gamma = {'Delta': 34, 'Epsilon': 74, 'Zeta': 51, 'Eta': 25, 'Theta': 43, 'Iota': 82, 'Kappa': 23}

# From Plant Delta
cost_Delta = {'Delta': 9, 'Epsilon': 2, 'Zeta': 9, 'Eta': 3, 'Theta': 1, 'Iota': 3, 'Kappa': 9}
cap_Delta = {'Delta': 63, 'Epsilon': 13, 'Zeta': 13, 'Eta': 66, 'Theta': 55, 'Iota': 77, 'Kappa': 57}

# From Plant Epsilon
cost_Epsilon = {'Delta': 7, 'Epsilon': 10, 'Zeta': 4, 'Eta': 8, 'Theta': 7, 'Iota': 5, 'Kappa': 1}
cap_Epsilon = {'Delta': 76, 'Epsilon': 16, 'Zeta': 38, 'Eta': 66, 'Theta': 34, 'Iota': 19, 'Kappa': 42}

# From Plant Zeta
cost_Zeta = {'Delta': 10, 'Epsilon': 3, 'Zeta': 7, 'Eta': 3, 'Theta': 8, 'Iota': 10, 'Kappa': 1}
cap_Zeta = {'Delta': 23, 'Epsilon': 51, 'Zeta': 17, 'Eta': 22, 'Theta': 89, 'Iota': 12, 'Kappa': 90}

# From Plant Eta
cost_Eta = {'Delta': 7, 'Epsilon': 2, 'Zeta': 10, 'Eta': 7, 'Theta': 6, 'Iota': 4, 'Kappa': 9}
cap_Eta = {'Delta': 22, 'Epsilon': 80, 'Zeta': 76, 'Eta': 30, 'Theta': 5, 'Iota': 9, 'Kappa': 56}

# Combine into dictionaries
transmission_cost = {
    'Alpha': cost_Alpha,
    'Beta': cost_Beta,
    'Gamma': cost_Gamma,
    'Delta': cost_Delta,
    'Epsilon': cost_Epsilon,
    'Zeta': cost_Zeta,
    'Eta': cost_Eta
}

transmission_capacity = {
    'Alpha': cap_Alpha,
    'Beta': cap_Beta,
    'Gamma': cap_Gamma,
    'Delta': cap_Delta,
    'Epsilon': cap_Epsilon,
    'Zeta': cap_Zeta,
    'Eta': cap_Eta
}

# Decision variables: x[plant][center] = MW transmitted (continuous, non-negative)
x = pulp.LpVariable.dicts("x", 
                          ((p, c) for p in plants for c in centers),
                          lowBound=0,
                          cat='Continuous')

# Objective function: minimize total transmission cost
model += pulp.lpSum([x[p, c] * transmission_cost[p][c] for p in plants for c in centers]), "Total_Transmission_Cost"

# Constraints

# Supply constraints: total from each plant <= plant capacity
for p in plants:
    model += pulp.lpSum([x[p, c] for c in centers]) <= plant_capacity[p], f"Supply_{p}"

# Demand constraints: total to each center = center demand
for c in centers:
    model += pulp.lpSum([x[p, c] for p in plants]) == center_demand[c], f"Demand_{c}"

# Transmission capacity constraints: each line <= its capacity
for p in plants:
    for c in centers:
        model += x[p, c] <= transmission_capacity[p][c], f"Capacity_{p}_{c}"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total Cost: {pulp.value(model.objective)}")
print("\nTransmission Plan:")
for p in plants:
    for c in centers:
        val = pulp.value(x[p, c])
        if val > 0.001:
            print(f"  {p} -> {c}: {val:.2f} MW (cost {transmission_cost[p][c]}/MW)")

import pulp

# Define plants and their maximum outputs
plants = {
    'Alpha': 11,
    'Beta': 23,
    'Gamma': 10,
    'Delta': 23,
    'Epsilon': 52,
    'Zeta': 36,
    'Eta': 49,
    'Theta': 79
}

# Define zones and their requirements
zones = {
    'D': 0,
    'E': 0,
    'F': 26,
    'G': 21,
    'H': 23,
    'I': 79,
    'J': 88,
    'K': 46
}

# Transmission data: (capacity, cost)
