# Create the problem
model = pulp.LpProblem("Blood_Bank_TSP", pulp.LpMinimize)

# Centers: 1, 2, 3, 4
centers = [1, 2, 3, 4]
n = len(centers)

# Travel times (symmetric)
dist = {
    (1, 2): 197.5, (2, 1): 197.5,
    (1, 3): 251.0, (3, 1): 251.0,
    (1, 4): 216.8, (4, 1): 216.8,
    (2, 3): 98.0,  (3, 2): 98.0,
    (2, 4): 59.4,  (4, 2): 59.4,
    (3, 4): 41.2,  (4, 3): 41.2,
}

# Add zero self-distances
for i in centers:
    dist[(i, i)] = 0

# Decision variables: x[i][j] = 1 if travel from i to j
x = {}
for i in centers:
    for j in centers:
        if i != j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", lowBound=0, upBound=1, cat='Binary')

# Subtour elimination variables (MTZ formulation): u[i] = position in tour
# u[1] = 1 (fixed), others in [2, n]
u = {}
for i in centers:
    if i == 1:
        u[i] = 1  # fixed
    else:
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=2, upBound=n, cat='Continuous')

# Objective: minimize total travel time
model += pulp.lpSum([dist[(i, j)] * x[(i, j)] for i in centers for j in centers if i != j])

# Constraints: leave each center exactly once
for i in centers:
    model += pulp.lpSum([x[(i, j)] for j in centers if i != j]) == 1

# Constraints: enter each center exactly once
for j in centers:
    model += pulp.lpSum([x[(i, j)] for i in centers if i != j]) == 1

# Subtour elimination constraints (MTZ)
# u[i] - u[j] + n * x[i][j] <= n - 1 for all i != j, i, j != 1
for i in centers:
    for j in centers:
        if i != j and i != 1 and j != 1:
            model += u[i] - u[j] + n * x[(i, j)] <= n - 1

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total travel time: {pulp.value(model.objective):.1f} minutes")
print("\nRoute:")
for i in centers:
    for j in centers:
        if i != j and pulp.value(x[(i, j)]) > 0.5:
            print(f"  {i} -> {j}: {dist[(i, j)]} minutes")

