dist = {
    (1, 2): 197.5, (2, 1): 197.5,
    (1, 3): 251.0, (3, 1): 251.0,
    (1, 4): 216.8, (4, 1): 216.8,
    (2, 3): 98.0,  (3, 2): 98.0,
    (2, 4): 59.4,  (4, 2): 59.4,
    (3, 4): 41.2,  (4, 3): 41.2,
}

# Binary decision variables: x[i,j] = 1 if travel from center i to center j
x = {}
for i in centers:
    for j in centers:
        if i != j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Integer decision variables for subtour elimination (MTZ formulation)
# u[i] represents position of center i in the tour (1 is start, so u[1]=1)
# For other centers, u[i] in {2, 3, 4}
u = {}
