# Constraint: enter each center exactly once
for j in centers:
    model += pulp.lpSum([x[(i, j)] for i in centers if i != j]) == 1

# Subtour elimination constraints (Miller-Tucker-Zemlin)
for i in [2, 3, 4]:
    for j in [2, 3, 4]:
        if i != j:
