    (8, 9): 87.5, (8, 10): 113.6,
    (9, 10): 140.7
}

# Function to get travel time between any two centers
def get_time(i, j):
    if i == j:
        return 0
    if i < j:
        return travel_times.get((i, j), 0)
    else:
        return travel_times.get((j, i), 0)

# Decision variables: x[i][j] = 1 if we travel from center i to center j
x = {}
for i in range(1, n + 1):
    for j in range(1, n + 1):
        if i != j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Auxiliary variables for subtour elimination (MTZ formulation)
# u[i] represents the position of center i in the tour (1 to n)
u = {}
for i in range(1, n + 1):
    u[i] = pulp.LpVariable(f"u_{i}", lowBound=1, upBound=n, cat='Continuous')

# Objective function: minimize total travel time
model += pulp.lpSum(get_time(i, j) * x[(i, j)] for i in range(1, n + 1) for j in range(1, n + 1) if i != j)

