# Each center is exited exactly once
for i in range(1, n + 1):
    model += pulp.lpSum(x[(i, j)] for j in range(1, n + 1) if i != j) == 1

# Each center is entered exactly once
for j in range(1, n + 1):
    model += pulp.lpSum(x[(i, j)] for i in range(1, n + 1) if i != j) == 1

