import pulp

# Define the problem
model = pulp.LpProblem("Job_Shop_Scheduling", pulp.LpMinimize)

# Data: Products and their operations (station, duration)
# Stations: A=0, B=1, C=2, D=3, E=4
station_map = {'A': 0, 'B': 1, 'C': 2, 'D': 3, 'E': 4}

products = {
    1: [('B', 1), ('E', 2), ('D', 7), ('A', 5), ('C', 2)],  # P1
    2: [('E', 4), ('C', 2), ('A', 9), ('B', 5), ('D', 6)],  # P2
    3: [('B', 10), ('C', 3), ('D', 3), ('E', 1), ('A', 9)],  # P3
    4: [('E', 7), ('C', 3), ('B', 3), ('A', 9), ('D', 2)],  # P4
    5: [('B', 3), ('E', 4), ('D', 7), ('A', 6), ('C', 10)],  # P5
}

num_jobs = 5
num_operations = 5  # Each product has 5 operations

# Extract processing times and machine assignments
# p[j][k] = duration, m[j][k] = machine index
p = {}  # processing times
m = {}  # machine assignments

for j in range(1, num_jobs + 1):
    p[j] = {}
    m[j] = {}
    for k in range(num_operations):
        station_char, duration = products[j][k]
        p[j][k] = duration
        m[j][k] = station_map[station_char]

# Big-M constant (upper bound on makespan)
# Sum of all processing times is a safe upper bound
M = sum(sum(p[j][k] for k in range(num_operations)) for j in range(1, num_jobs + 1))

# Decision Variables
# s[j][k] = start time of operation k of job j
s = {}
for j in range(1, num_jobs + 1):
    s[j] = {}
    for k in range(num_operations):
        s[j][k] = pulp.LpVariable(f"s_{j}_{k}", lowBound=0, cat='Continuous')

# C_max = makespan
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# y[(j,k,j2,k2)] = binary: 1 if operation (j,k) precedes (j2,k2) when same machine
# Only needed for pairs of operations on the same machine
y = {}
for j in range(1, num_jobs + 1):
    for k in range(num_operations):
        for j2 in range(j, num_jobs + 1):  # j2 >= j to avoid duplicates
            for k2 in range(num_operations):
                if j == j2 and k >= k2:
                    continue  # skip same operation or same job with k >= k2
                if m[j][k] == m[j2][k2]:  # same machine
                    y[(j, k, j2, k2)] = pulp.LpVariable(f"y_{j}_{k}_{j2}_{k2}", cat='Binary')

# Objective: minimize makespan
model += C_max

# Constraint 1: Precedence constraints (operations within same job)
for j in range(1, num_jobs + 1):
    for k in range(num_operations - 1):
        model += s[j][k + 1] >= s[j][k] + p[j][k], f"precedence_{j}_{k}"

# Constraint 2: Resource constraints (no two operations on same machine simultaneously)
for j in range(1, num_jobs + 1):
    for k in range(num_operations):
        for j2 in range(j, num_jobs + 1):
            for k2 in range(num_operations):
                if j == j2 and k >= k2:
                    continue
                if m[j][k] == m[j2][k2]:  # same machine
                    # If y=1: (j,k) before (j2,k2)
                    model += s[j][k] + p[j][k] <= s[j2][k2] + M * (1 - y[(j, k, j2, k2)]), f"resource_1_{j}_{k}_{j2}_{k2}"
                    # If y=0: (j2,k2) before (j,k)
                    model += s[j2][k2] + p[j2][k2] <= s[j][k] + M * y[(j, k, j2, k2)], f"resource_2_{j}_{k}_{j2}_{k2}"

# Constraint 3: Makespan definition (last operation of each job)
for j in range(1, num_jobs + 1):
    model += C_max >= s[j][num_operations - 1] + p[j][num_operations - 1], f"makespan_{j}"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal Makespan (C_max): {pulp.value(C_max)}")

print("\nSchedule by Product:")
for j in range(1, num_jobs + 1):
    print(f"\nProduct P{j}:")
    for k in range(num_operations):
        start = pulp.value(s[j][k])
        end = start + p[j][k]
        station_idx = m[j][k]
        station_name = ['A', 'B', 'C', 'D', 'E'][station_idx]
        print(f"  Op {k+1}: Station {station_name}, Start={start:.1f}, End={end:.1f}, Duration={p[j][k]}")

print("\nSchedule by Station:")
for station_idx in range(5):
    station_name = ['A', 'B', 'C', 'D', 'E'][station_idx]
    print(f"\nStation {station_name}:")
    station_ops = []
    for j in range(1, num_jobs + 1):
        for k in range(num_operations):
            if m[j][k] == station_idx:
                start = pulp.value(s[j][k])
                end = start + p[j][k]
                station_ops.append((start, end, j, k))
    station_ops.sort()
    for start, end, j, k in station_ops:
        print(f"  P{j} Op{k+1}: [{start:.1f}, {end:.1f}]")

import pulp

# Problem data
routes = {
    1: [('C', 5), ('B', 5), ('A', 7), ('D', 7)],
    2: [('D', 4), ('A', 5), ('C', 6), ('B', 1)],
    3: [('A', 8), ('B', 10), ('C', 2), ('D', 3)],
    4: [('C', 7), ('B', 8), ('A', 1), ('D', 2)],
}

# Build operation list: (route, operation_index, hub, duration)
operations = []
for r in routes:
    for idx, (hub, dur) in enumerate(routes[r]):
        operations.append((r, idx, hub, dur))

# Map (route, op_index) to (hub, duration) for quick lookup
op_info = {}
for r, idx, hub, dur in operations:
    op_info[(r, idx)] = (hub, dur)

# Group operations by hub
hub_ops = {'A': [], 'B': [], 'C': [], 'D': []}
for r, idx, hub, dur in operations:
    hub_ops[hub].append((r, idx))

# Calculate big-M: sum of all durations
total_duration = sum(dur for _, _, _, dur in operations)
M = total_duration  # 91

# Create model
model = pulp.LpProblem("JobShop_Scheduling", pulp.LpMinimize)

# Decision variables: start times (continuous)
s = {}
for r, idx, hub, dur in operations:
    s[(r, idx)] = pulp.LpVariable(f"s_{r}_{idx}", lowBound=0, cat='Continuous')

# Makespan
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Binary variables for ordering on same hub
y = {}
for hub in hub_ops:
    ops_on_hub = hub_ops[hub]
    for i, (r1, idx1) in enumerate(ops_on_hub):
        for (r2, idx2) in ops_on_hub[i+1:]:
            y[(r1, idx1, r2, idx2)] = pulp.LpVariable(f"y_{r1}_{idx1}_{r2}_{idx2}", cat='Binary')

# Objective: minimize makespan
model += C_max

# Constraint 1: Makespan definition - all operations finish before C_max
for r, idx, hub, dur in operations:
    model += s[(r, idx)] + dur <= C_max, f"makespan_{r}_{idx}"

# Constraint 2: Precedence constraints within each route
for r in routes:
    for idx in range(len(routes[r]) - 1):
        dur_current = routes[r][idx][1]
        model += s[(r, idx)] + dur_current <= s[(r, idx + 1)], f"precedence_{r}_{idx}"

# Constraint 3: No-overlap constraints on each hub
for hub in hub_ops:
    ops_on_hub = hub_ops[hub]
    for i, (r1, idx1) in enumerate(ops_on_hub):
        for (r2, idx2) in ops_on_hub[i+1:]:
            dur1 = op_info[(r1, idx1)][1]
            dur2 = op_info[(r2, idx2)][1]
            var = y[(r1, idx1, r2, idx2)]

            # If y=1: (r1,idx1) before (r2,idx2)
            model += s[(r1, idx1)] + dur1 <= s[(r2, idx2)] + M * (1 - var), f"no_overlap_1_{r1}_{idx1}_{r2}_{idx2}"
            # If y=0: (r2,idx2) before (r1,idx1)
            model += s[(r2, idx2)] + dur2 <= s[(r1, idx1)] + M * var, f"no_overlap_2_{r1}_{idx1}_{r2}_{idx2}"

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Optimal makespan: {pulp.value(C_max)}")
print("\nSchedule:")
for r in sorted(routes.keys()):
    print(f"\nRoute {r}:")
    for idx in range(len(routes[r])):
        hub, dur = routes[r][idx]
        start = pulp.value(s[(r, idx)])
        print(f"  {hub}: start={start:.1f}, end={start+dur:.1f}, duration={dur}")

