import pulp

# Data from the problem
# Patients/jobs: 1, 2, 3, 4
# Equipment/machines: A, B, C, D

# For each patient: list of (equipment, duration) in order
job_data = {
    1: [('C', 5), ('B', 5), ('A', 7), ('D', 7)],
    2: [('D', 4), ('A', 5), ('C', 6), ('B', 1)],
    3: [('A', 8), ('B', 10), ('C', 2), ('D', 3)],
    4: [('C', 7), ('B', 8), ('A', 1), ('D', 2)]
}

jobs = list(job_data.keys())  # [1, 2, 3, 4]
num_operations = 4  # Each job has 4 operations

# Build machine assignment and duration matrices
# machine[j][o] = equipment for operation o of job j
# duration[j][o] = duration for operation o of job j
machine = {}
duration = {}
for j in jobs:
    machine[j] = {}
    duration[j] = {}
    for o in range(num_operations):
        machine[j][o] = job_data[j][o][0]
        duration[j][o] = job_data[j][o][1]

# Big-M value (upper bound on makespan)
# Upper bound: sum of all durations = 5+5+7+7 + 4+5+6+1 + 8+10+2+3 + 7+8+1+2 = 90
M_big = 100

# Create model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Decision variables

# Start time of operation o of job j (continuous, >= 0)
s = {}
for j in jobs:
    for o in range(num_operations):
        s[j, o] = pulp.LpVariable(f"s_{j}_{o}", lowBound=0, cat='Continuous')

# Binary variables for sequencing on same machine
# y[j1,o1,j2,o2] = 1 if (j1,o1) precedes (j2,o2), 0 otherwise
# Only needed when two operations use the same machine and are from different jobs
y = {}

# Find all operations that use the same machine
for j1 in jobs:
    for o1 in range(num_operations):
        for j2 in jobs:
            if j2 <= j1:  # Avoid duplicates and self-pairs
                continue
            for o2 in range(num_operations):
                if machine[j1][o1] == machine[j2][o2]:  # Same machine
                    y[j1, o1, j2, o2] = pulp.LpVariable(f"y_{j1}_{o1}_{j2}_{o2}", cat='Binary')

# Makespan (continuous)
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += C_max

# Constraint 1: Precedence constraints within each job
for j in jobs:
    for o in range(num_operations - 1):
        model += s[j, o + 1] >= s[j, o] + duration[j][o]

# Constraint 2: Disjunctive constraints for same machine
for j1 in jobs:
    for o1 in range(num_operations):
        for j2 in jobs:
            if j2 <= j1:
                continue
            for o2 in range(num_operations):
                if machine[j1][o1] == machine[j2][o2]:  # Same machine
                    # Either (j1,o1) before (j2,o2) OR (j2,o2) before (j1,o1)
                    # If y = 1: s[j2,o2] >= s[j1,o1] + duration[j1][o1]
                    # If y = 0: s[j1,o1] >= s[j2,o2] + duration[j2][o2]
                    model += s[j2, o2] >= s[j1, o1] + duration[j1][o1] - M_big * (1 - y[j1, o1, j2, o2])
                    model += s[j1, o1] >= s[j2, o2] + duration[j2][o2] - M_big * y[j1, o1, j2, o2]

# Constraint 3: Makespan constraints
for j in jobs:
    model += C_max >= s[j, num_operations - 1] + duration[j][num_operations - 1]

# Solve with HiGHS
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal Makespan: {pulp.value(C_max)}")

print("\nSchedule:")
