    for idx, (d, _) in enumerate(sequences[t]):
        order[t][d] = idx

# Build list of operations per truck in sequence
ops_in_seq = {}
for t in trucks:
    ops_in_seq[t] = [d for d, _ in sequences[t]]

# Big-M value (upper bound on makespan)
M = 1000

# Create model
model = pulp.LpProblem("JobShop_Scheduling", pulp.LpMinimize)

# Decision variables
# Start time of each truck at each dock it visits
start = {}
for t in trucks:
    for d in ops_in_seq[t]:
        start[(t, d)] = pulp.LpVariable(f"start_{t}_{d}", lowBound=0, cat='Continuous')

# Binary variables for disjunction: y[t1,t2,d] = 1 if t1 before t2 at dock d
y = {}
for d in docks:
    # Find which trucks visit this dock
    trucks_at_d = [t for t in trucks if d in ops_in_seq[t]]
    for i, t1 in enumerate(trucks_at_d):
        for t2 in trucks_at_d[i+1:]:
            y[(t1, t2, d)] = pulp.LpVariable(f"y_{t1}_{t2}_{d}", cat='Binary')

# Makespan variable
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += makespan

# Constraints

# 1. Sequence constraints: operations must follow in order for each truck
for t in trucks:
    for i in range(len(ops_in_seq[t]) - 1):
        d_curr = ops_in_seq[t][i]
        d_next = ops_in_seq[t][i + 1]
        # start of next >= completion of current
        model += start[(t, d_next)] >= start[(t, d_curr)] + proc_time[t][d_curr]

# 2. Resource constraints: no two trucks at same dock simultaneously
# Using big-M formulation
for d in docks:
    trucks_at_d = [t for t in trucks if d in ops_in_seq[t]]
    for i, t1 in enumerate(trucks_at_d):
        for t2 in trucks_at_d[i+1:]:
            # Either t1 before t2 or t2 before t1
            # t1 before t2: start[t2,d] >= start[t1,d] + proc_time[t1,d]
            # t2 before t1: start[t1,d] >= start[t2,d] + proc_time[t2,d]
            model += start[(t2, d)] >= start[(t1, d)] + proc_time[t1][d] - M * (1 - y[(t1, t2, d)])
            model += start[(t1, d)] >= start[(t2, d)] + proc_time[t2][d] - M * y[(t1, t2, d)]

# 3. Makespan constraints: must be >= completion time of all operations
for t in trucks:
    last_dock = ops_in_seq[t][-1]
    model += makespan >= start[(t, last_dock)] + proc_time[t][last_dock]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal Makespan: {pulp.value(makespan)}")

print("\nSchedule:")
for t in trucks:
    print(f"\n{t}:")
    for d in ops_in_seq[t]:
        s = pulp.value(start[(t, d)])
        p = proc_time[t][d]
        print(f"  {d}: start={s:.1f}, end={s+p:.1f}, duration={p}")

import pulp

# Define the problem
model = pulp.LpProblem("Job_Shop_Scheduling", pulp.LpMinimize)

# Data
jobs = ['Alpha', 'Beta', 'Gamma']
machines = ['A', 'B', 'C']
operations = [1, 2, 3]  # Each job has 3 operations

# Processing times and machine assignments for each job
# Format: job -> [(machine, duration), ...] in order
job_data = {
    'Alpha': [('B', 10), ('A', 7), ('C', 10)],
    'Beta': [('B', 6), ('C', 2), ('A', 6)],
    'Gamma': [('C', 10), ('A', 6), ('B', 4)]
}

# Map to easier access: p[job, op] = duration, mu[job, op] = machine
p = {}
mu = {}
for job in jobs:
    for op_idx, (mach, dur) in enumerate(job_data[job], 1):
        p[(job, op_idx)] = dur
        mu[(job, op_idx)] = mach

# Big-M: upper bound on makespan (sum of all durations)
M = sum(p.values())  # 61

# Decision Variables
# Completion time of each operation
C = pulp.LpVariable.dicts("C", ((job, op) for job in jobs for op in operations), lowBound=0, cat='Continuous')

# Makespan
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# Binary variables for disjunctive constraints (precedence on same machine)
# y[(job1, op1), (job2, op2)] = 1 if (job1,op1) precedes (job2,op2) on same machine
y = {}
for job1 in jobs:
    for op1 in operations:
        for job2 in jobs:
            for op2 in operations:
                if (job1, op1) < (job2, op2) and mu[(job1, op1)] == mu[(job2, op2)]:
                    # Only create for pairs on same machine, avoid duplicates
                    y[((job1, op1), (job2, op2))] = pulp.LpVariable(f"y_{job1}_{op1}_{job2}_{op2}", cat='Binary')

# Objective: minimize makespan
model += Cmax

# Constraints

# 1. Precedence constraints: operations in a job must be in sequence
for job in jobs:
    for op in range(2, 4):  # op 2 and 3
        model += C[(job, op)] >= C[(job, op-1)] + p[(job, op)], f"Prec_{job}_{op}"

# 2. First operation must finish after its processing time
for job in jobs:
    model += C[(job, 1)] >= p[(job, 1)], f"First_op_{job}"

# 3. Disjunctive constraints: machine capacity
for job1 in jobs:
    for op1 in operations:
        for job2 in jobs:
            for op2 in operations:
                if (job1, op1) < (job2, op2) and mu[(job1, op1)] == mu[(job2, op2)]:
                    # Same machine, different operations
                    # Either (job1,op1) before (job2,op2) or vice versa
                    y_var = y[((job1, op1), (job2, op2))]

                    # If y=1: (job1,op1) before (job2,op2)
                    model += C[(job1, op1)] + p[(job2, op2)] <= C[(job2, op2)] + M * (1 - y_var), f"Disj1_{job1}_{op1}_{job2}_{op2}"

                    # If y=0: (job2,op2) before (job1,op1)
                    model += C[(job2, op2)] + p[(job1, op1)] <= C[(job1, op1)] + M * y_var, f"Disj2_{job1}_{op1}_{job2}_{op2}"

# 4. Makespan constraints: Cmax >= completion time of last operation of each job
for job in jobs:
    model += Cmax >= C[(job, 3)], f"Makespan_{job}"

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal Makespan: {pulp.value(Cmax)}")

print("\nSchedule:")
for job in jobs:
    print(f"\n{job}:")
    for op in operations:
        start = pulp.value(C[(job, op)]) - p[(job, op)]
        end = pulp.value(C[(job, op)])
        print(f"  Operation {op} on {mu[(job, op)]}: [{start:.1f}, {end:.1f}] (duration {p[(job, op)]})")

# Verify machine usage
print("\nMachine usage verification:")
for mach in machines:
    print(f"\nMachine {mach}:")
    ops_on_mach = [(job, op) for job in jobs for op in operations if mu[(job, op)] == mach]
    ops_on_mach.sort(key=lambda x: pulp.value(C[x]) - p[x])
    for (job, op) in ops_on_mach:
        start = pulp.value(C[(job, op)]) - p[(job, op)]
        end = pulp.value(C[(job, op)])
        print(f"  {job} op {op}: [{start:.1f}, {end:.1f}]")

import pulp

# Data: trucks and their sequences (route, processing_time)
truck_data = {
    1: [(8, 3), (6, 4), (7, 8), (4, 6), (3, 1), (2, 6), (5, 8), (1, 10)],
    2: [(5, 7), (6, 10), (2, 6), (1, 9), (8, 3), (7, 1), (4, 8), (3, 7)],
    3: [(8, 8), (7, 3), (4, 2), (3, 9), (1, 9), (6, 7), (5, 10), (2, 5)],
    4: [(4, 4), (1, 10), (8, 5), (7, 7), (6, 8), (3, 9), (2, 5), (5, 2)],
    5: [(1, 8), (8, 7), (3, 9), (4, 1), (5, 7), (2, 5), (7, 8), (6, 3)],
    6: [(7, 7), (6, 10), (4, 3), (8, 6), (3, 1), (2, 7), (5, 8), (1, 8)],
    7: [(5, 10), (1, 6), (6, 3), (2, 3), (3, 8), (7, 2), (8, 2), (4, 3)],
    8: [(1, 3), (2, 5), (6, 7), (7, 8), (8, 5), (3, 9), (5, 1), (4, 3)],
}

num_trucks = 8
num_routes = 8

# Build processing time matrix p[i][j] and operation sequence for each truck
# p[i][j] = processing time of truck i on route j
p = {}
# seq[i][m] = (route, time) for truck i, m-th operation (0-indexed)
seq = {}

for i in range(1, num_trucks + 1):
    p[i] = {}
    seq[i] = {}
    for m, (route, time) in enumerate(truck_data[i]):
        p[i][route] = time
        seq[i][m] = (route, time)

# Big M for disjunctive constraints
M = 1000

# Create model
model = pulp.LpProblem("JobShop_Scheduling", pulp.LpMinimize)

# Decision variables
# s[i][j] = start time of truck i on route j
s = {}
for i in range(1, num_trucks + 1):
    s[i] = {}
    for j in range(1, num_routes + 1):
        s[i][j] = pulp.LpVariable(f"s_{i}_{j}", lowBound=0, cat='Continuous')

# C_max = makespan
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Binary variables for disjunctive constraints: y[i,k,j] = 1 if truck i precedes truck k on route j
y = {}
for j in range(1, num_routes + 1):
    y[j] = {}
    for i in range(1, num_trucks + 1):
        y[j][i] = {}
        for k in range(i + 1, num_trucks + 1):
            y[j][i][k] = pulp.LpVariable(f"y_{i}_{k}_{j}", cat='Binary')

# Objective: minimize makespan
model += C_max

# Constraint 1: Precedence constraints for each truck (operations in sequence)
for i in range(1, num_trucks + 1):
    for m in range(1, 8):  # 7 precedence constraints per truck (8 operations)
        route_prev, time_prev = seq[i][m - 1]
        route_curr, time_curr = seq[i][m]
        # Start of current operation >= finish of previous operation
        model += s[i][route_curr] >= s[i][route_prev] + time_prev

# Constraint 2: Makespan >= finish time of last operation of each truck
for i in range(1, num_trucks + 1):
    route_last, time_last = seq[i][7]  # 8th operation (index 7)
    model += C_max >= s[i][route_last] + time_last

# Constraint 3: Disjunctive constraints - no two trucks on same route simultaneously
for j in range(1, num_routes + 1):
    for i in range(1, num_trucks + 1):
        for k in range(i + 1, num_trucks + 1):
            # Either i before k: s[k][j] >= s[i][j] + p[i][j]
            # Or k before i: s[i][j] >= s[k][j] + p[k][j]
            model += s[k][j] >= s[i][j] + p[i][j] - M * (1 - y[j][i][k])
            model += s[i][j] >= s[k][j] + p[k][j] - M * y[j][i][k]

# Solve
model.solve(pulp.HiGHS(msg=True, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal makespan: {pulp.value(C_max)}")
print("\nSchedule:")
for i in range(1, num_trucks + 1):
    print(f"Truck {i}:")
    for m in range(8):
        route, time = seq[i][m]
        start = pulp.value(s[i][route])
        print(f"  Route {route}: start={start:.2f}, finish={start+time:.2f}, duration={time}")

