    u[i] = pulp.LpVariable(f"u_{i}", lowBound=1, upBound=8, cat='Integer')

# Objective: minimize total travel time
model += pulp.lpSum(get_dist(i, j) * x[(i, j)] 
                    for i in locations for j in locations if i != j)

# Constraints: each location entered exactly once
for j in locations:
    model += pulp.lpSum(x[(i, j)] for i in locations if i != j) == 1

# Constraints: each location exited exactly once
